    /** @param  list<array<string, mixed>>  $questions */
    private function questions(array $questions): void
    {
        $epreuve = Epreuve::where('code', 'ce')->firstOrFail();
        $epreuve->questions()->whereNotNull('niveau')->delete();

        foreach ($questions as $ordre => $question) {
            $epreuve->questions()->create($question + ['ordre' => $ordre]);
        }
    }
}
